// In Bus Fever Party!, each logical queue entry represents a 4-abreast row of 4 people (CROWD_MULT = 4),
// so a 4-seat car displays 16 on its bay counter, a 6-seat bus displays 24, an 8-seat bus displays 32, and a 10-seat bus displays 40!
const CROWD_MULT = 4;
const TOTAL_BAY_SLOTS = 8; // [VIP] + 5 Unlocked + [+] + [+]

const COLOR_KEYS = ["RED", "BLUE", "GREEN", "YELLOW", "PURPLE", "ORANGE", "CYAN", "PINK"];
const POWER_COSTS = { UNDO: 80, VIP: 150, SHUFFLE: 180, MAGNET: 220, AIRLIFT: 300 };

const LIVERY_PALETTE = {
  RED:    { name: "Red",    bodyTop: "#F42C24", chassisSkirt: "#9E140E", roofCap: "#FF6E66", outline: "#5C0905", symbol: "STAR" },
  BLUE:   { name: "Blue",   bodyTop: "#1D7DFA", chassisSkirt: "#0B4699", roofCap: "#6EB0FF", outline: "#062859", symbol: "TRIANGLE" },
  GREEN:  { name: "Green",  bodyTop: "#28C840", chassisSkirt: "#147522", roofCap: "#74E886", outline: "#0A4212", symbol: "CLOVER" },
  YELLOW: { name: "Yellow", bodyTop: "#FFC700", chassisSkirt: "#B28600", roofCap: "#FFE26B", outline: "#594300", symbol: "LIGHTNING BOLT" },
  PURPLE: { name: "Purple", bodyTop: "#9B42F5", chassisSkirt: "#581B99", roofCap: "#C994FF", outline: "#2E0C52", symbol: "DIAMOND" },
  ORANGE: { name: "Orange", bodyTop: "#FF7A00", chassisSkirt: "#AD4F00", roofCap: "#FFB366", outline: "#572600", symbol: "HEXAGON" },
  CYAN:   { name: "Cyan",   bodyTop: "#00C4D6", chassisSkirt: "#007380", roofCap: "#6CEAF7", outline: "#003D45", symbol: "CRESCENT" },
  PINK:   { name: "Brown",  bodyTop: "#8C3B2B", chassisSkirt: "#541F15", roofCap: "#B86454", outline: "#2E100A", symbol: "HEART" }
};

const SQ2 = Math.SQRT2 / 2;
const DIR_KEYS = ["N", "NE", "E", "SE", "S", "SW", "W", "NW"];
const DIRECTIONS = {
  N:  { key: "N",  deg: 0,   dx: 0,    dy: 1,    ndx: 1,    ndy: 0,    diag: false },
  NE: { key: "NE", deg: 45,  dx: SQ2,  dy: SQ2,  ndx: SQ2,  ndy: -SQ2, diag: true  },
  E:  { key: "E",  deg: 90,  dx: 1,    dy: 0,    ndx: 0,    ndy: -1,   diag: false },
  SE: { key: "SE", deg: 135, dx: SQ2,  dy: -SQ2, ndx: -SQ2, ndy: -SQ2, diag: true  },
  S:  { key: "S",  deg: 180, dx: 0,    dy: -1,   ndx: -1,   ndy: 0,    diag: false },
  SW: { key: "SW", deg: 225, dx: -SQ2, dy: -SQ2, ndx: -SQ2, ndy: SQ2,  diag: true  },
  W:  { key: "W",  deg: 270, dx: -1,   dy: 0,    ndx: 0,    ndy: 1,    diag: false },
  NW: { key: "NW", deg: 315, dx: -SQ2, dy: SQ2,  ndx: SQ2,  ndy: SQ2,  diag: true  }
};

const TIER_KEYS = ["EASY", "NORMAL", "HARD", "BOSS"];
const TIER_INFO = {
  EASY:   { name: "Sarala Krama", baseGold: 10, color: "#1D7DFA", lip: "#0D4DA6" },
  NORMAL: { name: "Sarala Krama", baseGold: 10, color: "#1D7DFA", lip: "#0D4DA6" },
  HARD:   { name: "Jatila Krama", baseGold: 15, color: "#EA580C", lip: "#9A3412" },
  BOSS:   { name: "Chakravyuha",  baseGold: 20, color: "#9333EA", lip: "#581C87" }
};

// Unified Coherent Vehicle Dimensions (used 1:1 across Vehicle Area, Collision Raycast & Middle Waiting Bays):
// - Small Vehicle (Car / Taxi, cap=4, 16 pax): 0.54 wide x 0.94 long (~1.5x small grid cells long)
// - Medium Vehicle (Minibus / Van, cap=6, 24 pax): 0.68 wide x 1.42 long (~2.3x small grid cells long)
// - Large Bus (Transit Bus, cap=8, 32 pax): 0.80 wide x 1.86 long (~3.05x small grid cells long)
// - Jumbo Bus (Coach Bus, cap=10, 40 pax): 0.84 wide x 2.00 long (~3.28x small grid cells long)
const VEHICLE_GRID_CELL = 0.608; // Fine vehicle-area grid cell size (0.80 * 0.76 -> 13x16 small grids in the same vehicle area!)

function getVehicleDimensions(cap) {
  if (cap <= 4) return { width: 0.54, length: 0.94 };
  if (cap <= 6) return { width: 0.68, length: 1.42 };
  if (cap <= 8) return { width: 0.80, length: 1.86 };
  return { width: 0.84, length: 2.00 };
}

function getBayParkedWorldPos(bayIndex, vehicle, bounds = islandBounds) {
  const bayC = getBayCenter(bayIndex, TOTAL_BAY_SLOTS, bounds);
  const vDims = getVehicleDimensions(vehicle ? vehicle.capacity : 8);
  // Pull shorter vehicles neatly forward along the bay's -16 deg heading toward the front wheel-stop bumper bar!
  const frontPull = Math.max(0, (1.92 - vDims.length) * 0.36);
  const rad = (BAY_TILT_DEG * Math.PI) / 180;
  return {
    x: bayC.x + Math.sin(rad) * frontPull,
    y: bayC.y + Math.cos(rad) * frontPull
  };
}

function decodeLevel(levelId) {
  const idx = Math.max(0, Math.min(RAW_LEVELS.length - 1, levelId - 1));
  const raw = RAW_LEVELS[idx];
  const [id, tierIdx, score, gridW, gridH, rawVehs, rawTunnels, rawQueue, trace] = raw;

  const LOT_SCALE = 0.76;
  const lotCx = gridW / 2.0;
  const lotCy = gridH / 2.0;
  const scaleLotX = x => lotCx + (x - lotCx) * LOT_SCALE;
  const scaleLotY = y => lotCy + (y - lotCy) * LOT_SCALE;

  const vehicles = {};
  rawVehs.forEach(rv => {
    const [vId, cIdx, scIdx, cap, ax, ay, dIdx, isMyst] = rv;
    const dims = getVehicleDimensions(cap);
    vehicles[vId] = {
      id: vId,
      color: COLOR_KEYS[cIdx],
      secondaryColor: scIdx >= 0 ? COLOR_KEYS[scIdx] : null,
      capacity: cap,
      seatedCount: 0,
      subSeatedCount: 0,
      anchorX: scaleLotX(ax),
      anchorY: scaleLotY(ay),
      direction: DIRECTIONS[DIR_KEYS[dIdx]],
      state: "PARKED",
      isMystery: isMyst === 1,
      assignedBayIndex: null,
      arrivalOrder: 0,
      width: dims.width,
      length: dims.length
    };
  });

  const tunnels = rawTunnels.map(rt => {
    const [tId, tx, ty, tdIdx, sq] = rt;
    return {
      id: tId,
      anchorX: scaleLotX(tx),
      anchorY: scaleLotY(ty),
      exitDirection: DIRECTIONS[DIR_KEYS[tdIdx]],
      spawnQueue: sq.map(sv => {
        const [vId, cIdx, scIdx, cap, ax, ay, dIdx, isMyst] = sv;
        const dims = getVehicleDimensions(cap);
        return {
          id: vId,
          color: COLOR_KEYS[cIdx],
          secondaryColor: scIdx >= 0 ? COLOR_KEYS[scIdx] : null,
          capacity: cap,
          seatedCount: 0,
          subSeatedCount: 0,
          anchorX: scaleLotX(ax),
          anchorY: scaleLotY(ay),
          direction: DIRECTIONS[DIR_KEYS[dIdx]],
          state: "PARKED",
          isMystery: isMyst === 1,
          assignedBayIndex: null,
          arrivalOrder: 0,
          width: dims.width,
          length: dims.length
        };
      })
    };
  });

  const passengerQueue = [];
  let pCounter = 0;
  rawQueue.forEach(([cIdx, count, vip]) => {
    for (let i = 0; i < count; i++) {
      passengerQueue.push({
        id: "p_" + (pCounter++),
        color: COLOR_KEYS[cIdx],
        vipMoves: vip > 0 ? vip : null,
        hasSmiley: (pCounter > 0 && pCounter % 8 === 0)
      });
    }
  });

  // 8 Angled Waiting Bays:
  // Lock 1 additional bus parking bay so starting levels (and standard levels) have 4 unlocked bays:
  // Index 0: Gold [VIP] Bay (locked)
  // Index 1..4: 4 Unlocked Angled Bays (\)
  // Index 5..7: 3 Green [+] Extra Angled Bays (locked)
  const baseOpenCount = (id === 43 || id === 66) ? 5 : 4;
  const waitingBays = [];
  for (let i = 0; i < TOTAL_BAY_SLOTS; i++) {
    const isLocked = (i === 0 || i > baseOpenCount);
    waitingBays.push({
      index: i,
      isUnlocked: !isLocked,
      isVip: isLocked,
      labelType: i === 0 ? "VIP" : (i > baseOpenCount ? "PLUS" : "NORMAL"),
      occupantVehicleId: null,
      state: "EMPTY"
    });
  }

  return {
    levelId: id,
    difficultyTier: TIER_KEYS[tierIdx],
    difficultyScore: score,
    gridWidth: gridW,
    gridHeight: gridH,
    baseWaitingBays: baseOpenCount,
    vehicles,
    tunnels,
    waitingBays,
    passengerQueue,
    initialQueueSize: passengerQueue.length,
    verifiedSolutionTrace: trace.slice(),
    status: "PLAYING",
    dispatchedCount: 0,
    peakBaysOccupied: 0,
    powerUpsUsedCount: 0,
    stepCounter: 0
  };
}
